export interface PriorityQueue<T> {
  enqueue(item: T, priority: number): void;
  dequeue(): T | undefined;        // highest priority first
  peek(): T | undefined;
  readonly size: number;
}

// small N: a sorted array satisfies the interface and beats a hand-rolled heap
class SortedPq<T> implements PriorityQueue<T> {
  private a: Array<{ item: T; priority: number; seq: number }> = [];
  private seq = 0;                 // stable ties: equal priorities come out FIFO

  enqueue(item: T, priority: number): void {
    const e = { item, priority, seq: this.seq++ };
    let lo = 0, hi = this.a.length;
    while (lo < hi) { const m = (lo + hi) >> 1;
      if (cmp(this.a[m], e) <= 0) lo = m + 1; else hi = m; }
    this.a.splice(lo, 0, e);
  }
  dequeue() { return this.a.shift()?.item; }   // O(n) but V8's shift is optimised
  peek() { return this.a[0]?.item; }
  get size() { return this.a.length; }
}
// for Dijkstra-style frontiers, use an indexed heap for O(log n) decrease-key
// in Node.js, guard every operation with a mutex: no protection across await
